diff --git a/tests/web/e2e/W1/support/api.ts b/tests/web/e2e/W1/support/api.ts
new file mode 100644
index 00000000..faeb92fc
--- /dev/null
+++ b/tests/web/e2e/W1/support/api.ts
@@ -0,0 +1,185 @@
+// The live API the workbench's acceptance tests drive: started from this worktree on DOCKET_API_PORT (the port
+// the app's /api proxy is given), with a fresh SQLite file, once per Playwright run. Every worker of the run
+// shares it, through a lock and a state file in the OS temp directory; a detached reaper (reaper.mjs) stops it
+// when the run that started it has ended. An API already answering on the port that no W1 run started is used
+// as it is, and said so: its database may not be fresh.
+//
+// Nothing here is a test: a build or start failure is a setup fault, thrown as one, never a red.
+import { execFileSync, spawn, spawnSync } from 'node:child_process';
+import { closeSync, existsSync, mkdirSync, openSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { test as base } from '@playwright/test';
+
+/** The worktree the suite runs in (Playwright runs from src/web). */
+export const repoRoot = execFileSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' }).trim();
+
+export const apiPort = Number(process.env.DOCKET_API_PORT ?? 5080);
+/** The API itself, for a test's own setup and expected values. The app reaches it as /api/… through its proxy. */
+export const apiUrl = `http://localhost:${apiPort}`;
+
+const project = join(repoRoot, 'src', 'Uinsure.Policies.Api');
+const reaper = join(repoRoot, 'tests', 'web', 'e2e', 'W1', 'support', 'reaper.mjs');
+const stateDir = join(tmpdir(), `docket-w1-api-${apiPort}`);
+const lockDir = join(stateDir, 'lock');
+const stateFile = join(stateDir, 'state.json');
+
+interface State {
+  /** The Playwright runner the API was started for: every worker's parent. */
+  runner: number;
+  /** The `dotnet run` process, or null when the API was already answering and is not this suite's. */
+  pid: number | null;
+}
+
+const sleep = (ms: number): Promise<void> => new Promise((done) => setTimeout(done, ms));
+
+function alive(pid: number): boolean {
+  try {
+    process.kill(pid, 0);
+    return true;
+  } catch (error) {
+    return (error as NodeJS.ErrnoException).code === 'EPERM';
+  }
+}
+
+function stopTree(pid: number): void {
+  if (process.platform === 'win32') {
+    spawnSync('taskkill', ['/PID', String(pid), '/T', '/F'], { stdio: 'ignore', windowsHide: true });
+    return;
+  }
+  try {
+    process.kill(-pid, 'SIGTERM');
+  } catch {
+    // Already gone.
+  }
+}
+
+async function ready(): Promise<boolean> {
+  try {
+    const answer = await fetch(`${apiUrl}/health/ready`, { signal: AbortSignal.timeout(5000) });
+    return answer.status === 200;
+  } catch {
+    return false;
+  }
+}
+
+function readState(): State | null {
+  if (!existsSync(stateFile)) return null;
+  try {
+    return JSON.parse(readFileSync(stateFile, 'utf8')) as State;
+  } catch {
+    return null;
+  }
+}
+
+async function withLock<T>(work: () => Promise<T>): Promise<T> {
+  const deadline = Date.now() + 600_000;
+  for (;;) {
+    try {
+      mkdirSync(lockDir);
+      break;
+    } catch (error) {
+      if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
+      try {
+        // A lock left by a worker that died mid-start is stale after five minutes.
+        if (Date.now() - statSync(lockDir).mtimeMs > 300_000) rmSync(lockDir, { recursive: true, force: true });
+      } catch {
+        // Released between the two calls.
+      }
+      if (Date.now() > deadline) throw new Error(`setup: waited 10 minutes for the API lock at ${lockDir}`);
+      await sleep(250);
+    }
+  }
+  try {
+    return await work();
+  } finally {
+    rmSync(lockDir, { recursive: true, force: true });
+  }
+}
+
+async function start(runner: number): Promise<number> {
+  const build = spawnSync('dotnet', ['build', project, '-nologo', '-v', 'q'], {
+    cwd: repoRoot,
+    encoding: 'utf8',
+    timeout: 300_000,
+    windowsHide: true,
+  });
+  if (build.status !== 0) throw new Error(`setup: dotnet build of the API failed\n${build.stdout ?? ''}${build.stderr ?? ''}`);
+
+  // Each run's database and log are its own; an earlier run's are removed with it.
+  for (const name of readdirSync(stateDir)) {
+    if (!/^(policies|api)-\d+\./.test(name)) continue;
+    try {
+      rmSync(join(stateDir, name), { force: true });
+    } catch {
+      // Still held by a process on its way out; the next run removes it.
+    }
+  }
+  const db = join(stateDir, `policies-${runner}.db`);
+  const logPath = join(stateDir, `api-${runner}.log`);
+  const log = openSync(logPath, 'w');
+  const child = spawn('dotnet', ['run', '--no-build', '--no-launch-profile', '--project', project, '--urls', apiUrl], {
+    cwd: repoRoot,
+    detached: true,
+    windowsHide: true,
+    stdio: ['ignore', log, log],
+    env: { ...process.env, ASPNETCORE_ENVIRONMENT: 'Development', ConnectionStrings__Policies: `Data Source=${db}` },
+  });
+  closeSync(log);
+  child.unref();
+  const pid = child.pid;
+  if (pid === undefined) throw new Error('setup: dotnet run did not start');
+  spawn(process.execPath, [reaper, String(runner), String(pid)], { detached: true, windowsHide: true, stdio: 'ignore' }).unref();
+
+  for (let i = 0; i < 240; i += 1) {
+    if (await ready()) return pid;
+    if (!alive(pid)) break;
+    await sleep(500);
+  }
+  stopTree(pid);
+  const tail = existsSync(logPath) ? readFileSync(logPath, 'utf8').slice(-4000) : '';
+  throw new Error(`setup: the API did not answer ${apiUrl}/health/ready\n${tail}`);
+}
+
+/** The API answers on its port for this run, started fresh if this run has none yet. */
+export async function ensureApi(): Promise<void> {
+  mkdirSync(stateDir, { recursive: true });
+  const runner = process.ppid;
+  await withLock(async () => {
+    const state = readState();
+    // This run's API: another worker started it. A busy moment is waited out, never answered with a restart.
+    if (state !== null && state.runner === runner && (state.pid === null || alive(state.pid))) {
+      for (let i = 0; i < 120; i += 1) {
+        if (await ready()) return;
+        await sleep(500);
+      }
+      throw new Error(`setup: this run's API at ${apiUrl} stopped answering /health/ready`);
+    }
+    // An API a previous run left behind: stop it, so this run starts on a fresh database.
+    if (state?.pid != null && alive(state.pid)) {
+      stopTree(state.pid);
+      for (let i = 0; i < 30 && (await ready()); i += 1) await sleep(500);
+    }
+    rmSync(stateFile, { force: true });
+    if (await ready()) {
+      console.warn(`An API this suite did not start answers on ${apiUrl}; the W1 tests use it, and its database may not be fresh.`);
+      writeFileSync(stateFile, JSON.stringify({ runner, pid: null } satisfies State));
+      return;
+    }
+    const pid = await start(runner);
+    writeFileSync(stateFile, JSON.stringify({ runner, pid } satisfies State));
+  });
+}
+
+/** `test` with the live API: a test that names `api` runs with the API answering at that URL. */
+export const test = base.extend<object, { api: string }>({
+  api: [
+    async ({}, use) => {
+      await ensureApi();
+      await use(apiUrl);
+    },
+    { scope: 'worker', timeout: 600_000 },
+  ],
+});
+
+export { expect } from '@playwright/test';
diff --git a/tests/web/e2e/W1/support/parity.ts b/tests/web/e2e/W1/support/parity.ts
new file mode 100644
index 00000000..1e73841d
--- /dev/null
+++ b/tests/web/e2e/W1/support/parity.ts
@@ -0,0 +1,224 @@
+// Parity with W1's derived reference (docs/ui/derived/W1/), each built route brought to a reference state by the
+// recorded API answers that state names (docs/ui/fixture/api/), so both sides show the same exchange, and the
+// shell served the design fixture's trace.json. Structure only: the tagged regions in order (the unbuilt ones as
+// not built yet), the catalogued components in each, the shell, the title and the navigation, and tokens in
+// place of literal colours. Parity tests are the only ones that may pass at the stub, so a flow here never
+// asserts on behaviour: it does what a person would, and the comparison polls until the page matches or times out.
+//
+// wb-policy's long-content state is a fake-clock test (CancelRenewedPolicyTests), not an exchange the API can be
+// asked for, so no flow reaches it; its regions are the populated state's.
+import { expect } from '@playwright/test';
+import type { Page, Route } from '@playwright/test';
+import { serveTrace, setTheme, themes, viewports } from '../../U0b/support/app';
+import { literalColours } from '../../U0b/support/reference';
+import { REC, answerWith, exchangeAt } from './recorded';
+import type { RecordedExchange } from './recorded';
+import { designFixtureDir, readBuilt, readReference, regionNamed, regionOrder, unbuiltComps } from './reference';
+import type { Structure } from './reference';
+import { fillSell, formOf, hold, openButton, route, sellButton, typeOnHome, unreachable } from './workbench';
+import type { SellRequest } from './workbench';
+
+export interface Screen {
+  label: string;
+  screen: 'wb-home' | 'wb-sell' | 'wb-policy';
+  state: string;
+  /** Brings the page to the reference's state, from a fresh page. */
+  open(page: Page): Promise<void>;
+}
+
+const bodyOf = (exchange: RecordedExchange): SellRequest => exchange.requestBody as SellRequest;
+const sold = exchangeAt(REC.sold, 0);
+const soldReadBack = exchangeAt(REC.sold, 1);
+const refused = exchangeAt(REC.refused, 0);
+const otherSale = exchangeAt(REC.readBack, 0);
+const readBack = exchangeAt(REC.readBack, 1);
+const unknown = exchangeAt(REC.unknown, 0);
+
+/** POST /api/policies answered from the recording whose request carries the same reference. */
+async function answerSales(page: Page, sales: RecordedExchange[]): Promise<void> {
+  await page.route(
+    (url) => url.pathname === '/api/policies',
+    (handled: Route) => {
+      if (handled.request().method() !== 'POST') return handled.fallback();
+      const typed = (handled.request().postDataJSON() as { reference?: string } | null)?.reference ?? '';
+      const sale = sales.find((s) => bodyOf(s).reference === typed.trim().toUpperCase());
+      if (sale === undefined) return handled.fallback();
+      return handled.fulfill({ status: sale.status, contentType: 'application/json', body: JSON.stringify(sale.responseBody) });
+    },
+  );
+}
+
+/** Clicks Sell, and gives the answer a moment to land before the flow moves on (it may never come, at the stub). */
+async function sellAndSettle(page: Page): Promise<void> {
+  const answer = page.waitForResponse((r) => new URL(r.url()).pathname === '/api/policies', { timeout: 5000 }).catch(() => null);
+  await sellButton(page).click();
+  await answer;
+}
+
+export const homeStates: Record<'populated' | 'submitting' | 'unreachable', Screen> = {
+  populated: {
+    label: 'workbench home',
+    screen: 'wb-home',
+    state: 'populated',
+    // F1-MVFJOFJ8IS then F2-MVFJQA9DQG, both sold in this browser: the reference's list, newest first.
+    open: async (page) => {
+      await answerSales(page, [sold, otherSale]);
+      await answerWith(page, soldReadBack);
+      await answerWith(page, readBack);
+      await fillSell(page, formOf(bodyOf(sold)));
+      await sellAndSettle(page);
+      await fillSell(page, formOf(bodyOf(otherSale)));
+      await sellAndSettle(page);
+      await page.goto(route.home);
+    },
+  },
+  submitting: {
+    label: 'workbench home, opening a policy',
+    screen: 'wb-home',
+    state: 'submitting',
+    open: async (page) => {
+      await hold(page, 'GET', `/api${soldReadBack.path}`);
+      await typeOnHome(page, bodyOf(sold).reference);
+      await openButton(page).click();
+    },
+  },
+  unreachable: {
+    label: 'workbench home, the API not answering',
+    screen: 'wb-home',
+    state: 'api-unreachable',
+    open: async (page) => {
+      await unreachable(page, 'GET', `/api${soldReadBack.path}`);
+      await typeOnHome(page, bodyOf(sold).reference);
+      await openButton(page).click();
+    },
+  },
+};
+
+export const sellStates: Record<'populated' | 'submitting' | 'error' | 'unreachable', Screen> = {
+  populated: {
+    label: 'sell form, after a 201',
+    screen: 'wb-sell',
+    state: 'populated',
+    open: async (page) => {
+      await answerWith(page, sold);
+      await answerWith(page, soldReadBack);
+      await fillSell(page, formOf(bodyOf(sold)));
+      await sellButton(page).click();
+    },
+  },
+  submitting: {
+    label: 'sell form, the sale in flight',
+    screen: 'wb-sell',
+    state: 'submitting',
+    open: async (page) => {
+      await hold(page, 'POST', '/api/policies');
+      await fillSell(page, formOf(bodyOf(sold)));
+      await sellButton(page).click();
+    },
+  },
+  error: {
+    label: 'sell form, sent anyway and answered 422',
+    screen: 'wb-sell',
+    state: 'api-error',
+    open: async (page) => {
+      await answerWith(page, refused);
+      await fillSell(page, formOf(bodyOf(refused)), { sendAnyway: true });
+      await sellButton(page).click();
+    },
+  },
+  unreachable: {
+    label: 'sell form, the API not answering',
+    screen: 'wb-sell',
+    state: 'api-unreachable',
+    open: async (page) => {
+      await unreachable(page, 'POST', '/api/policies');
+      await fillSell(page, formOf(bodyOf(sold)));
+      await sellButton(page).click();
+    },
+  },
+};
+
+export const policyStates: Record<'populated' | 'error' | 'unreachable', Screen> = {
+  populated: {
+    label: 'policy view',
+    screen: 'wb-policy',
+    state: 'populated',
+    open: async (page) => {
+      await answerWith(page, readBack);
+      await page.goto(route.policy(readBack.path.replace('/policies/', '')));
+    },
+  },
+  error: {
+    label: 'policy view, answered 404',
+    screen: 'wb-policy',
+    state: 'api-error',
+    open: async (page) => {
+      await answerWith(page, unknown);
+      await page.goto(route.policy(unknown.path.replace('/policies/', '')));
+    },
+  },
+  unreachable: {
+    label: 'policy view, the API not answering',
+    screen: 'wb-policy',
+    state: 'api-unreachable',
+    open: async (page) => {
+      await unreachable(page, 'GET', `/api${readBack.path}`);
+      await page.goto(route.policy(readBack.path.replace('/policies/', '')));
+    },
+  },
+};
+
+async function prepare(page: Page, s: Screen): Promise<void> {
+  await serveTrace(page, designFixtureDir);
+  await setTheme(page, 'light');
+  await page.setViewportSize(viewports[1440]);
+  await s.open(page);
+}
+
+/** Every region of the reference, in its order, with its data-req; the unbuilt ones as the not-built-yet pattern. */
+export async function expectRegionsInOrder(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await prepare(page, s);
+  await expect
+    .poll(async () => {
+      const built = await readBuilt(page, reference);
+      return { order: regionOrder(built), unbuilt: unbuiltComps(built) };
+    })
+    .toEqual({ order: regionOrder(reference), unbuilt: unbuiltComps(reference) });
+}
+
+/** One region of the reference, with its data-req and the catalogued components inside it. */
+export async function expectRegionComponents(page: Page, s: Screen, slug: string): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  const wanted = regionNamed(reference, slug);
+  expect(wanted, `the reference has region ${slug}`).toBeDefined();
+  await prepare(page, s);
+  await expect
+    .poll(async () => {
+      const found = regionNamed(await readBuilt(page, reference), slug);
+      return found ? { req: found.req, comps: found.comps } : null;
+    })
+    .toEqual({ req: wanted?.req, comps: wanted?.comps });
+}
+
+function shellOf(s: Structure): Record<string, unknown> {
+  return { title: s.title, shell: s.shell, navLinks: s.navLinks, navNotBuilt: s.navNotBuilt, navCurrent: s.navCurrent };
+}
+
+/** The title, the shell's components and the primary nav (links, not-built entries, the current one). */
+export async function expectShell(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await prepare(page, s);
+  await expect.poll(async () => shellOf(await readBuilt(page, reference))).toEqual(shellOf(reference));
+}
+
+/** No colour on the page from a literal: the screen's styles, inline styles and SVG paint use tokens only. */
+export async function expectTokensOnly(page: Page, s: Screen): Promise<void> {
+  const reference = await readReference(page.context(), s.screen, s.state);
+  await prepare(page, s);
+  await expect.poll(async () => (await readBuilt(page, reference)).regions.length).toBe(reference.regions.length);
+  for (const theme of themes) {
+    await setTheme(page, theme);
+    expect.soft(await page.evaluate(literalColours), `literal colours, ${theme}`).toEqual([]);
+  }
+}
diff --git a/tests/web/e2e/W1/support/reaper.mjs b/tests/web/e2e/W1/support/reaper.mjs
new file mode 100644
index 00000000..2a87465f
--- /dev/null
+++ b/tests/web/e2e/W1/support/reaper.mjs
@@ -0,0 +1,38 @@
+// Stops the API the W1 suite started once the Playwright run that wanted it has ended.
+// Spawned detached by support/api.ts: node reaper.mjs <runner pid> <api pid>. It checks once a second and exits
+// as soon as the API is gone, by its hand or another's, so it never outlives the run by more than that second.
+import { spawnSync } from 'node:child_process';
+
+const [runner, api] = process.argv.slice(2).map(Number);
+
+function alive(pid) {
+  try {
+    process.kill(pid, 0);
+    return true;
+  } catch (error) {
+    return error.code === 'EPERM';
+  }
+}
+
+function stop(pid) {
+  if (process.platform === 'win32') {
+    spawnSync('taskkill', ['/PID', String(pid), '/T', '/F'], { stdio: 'ignore', windowsHide: true });
+    return;
+  }
+  try {
+    process.kill(-pid, 'SIGTERM');
+  } catch {
+    // Already gone.
+  }
+}
+
+const tick = setInterval(() => {
+  if (!alive(api)) {
+    clearInterval(tick);
+    return;
+  }
+  if (!alive(runner)) {
+    clearInterval(tick);
+    stop(api);
+  }
+}, 1000);
diff --git a/tests/web/e2e/W1/support/recorded.ts b/tests/web/e2e/W1/support/recorded.ts
new file mode 100644
index 00000000..e50f6d98
--- /dev/null
+++ b/tests/web/e2e/W1/support/recorded.ts
@@ -0,0 +1,64 @@
+// The workbench's design fixture: the API's real answers recorded in docs/ui/fixture/api/, the data the W1
+// screens were signed off on. For parity only: a parity flow answers the page's /api/… requests from a recording,
+// so the built route and its derived reference show the same exchange. Behaviour tests use the live API.
+import { readFileSync } from 'node:fs';
+import { join } from 'node:path';
+import type { Page, Route } from '@playwright/test';
+import { repoRoot } from './api';
+
+export const recordedDir = join(repoRoot, 'docs', 'ui', 'fixture', 'api');
+
+export interface RecordedExchange {
+  role: string;
+  method: string;
+  /** The API's path, /policies/… (the page asks for /api/policies/…). */
+  path: string;
+  requestBody: unknown;
+  status: number;
+  responseHeaders: Record<string, string>;
+  responseBody: unknown;
+}
+
+interface Recording {
+  item: string;
+  exchanges: RecordedExchange[];
+}
+
+export function recording(file: string): RecordedExchange[] {
+  return (JSON.parse(readFileSync(join(recordedDir, file), 'utf8')) as Recording).exchanges;
+}
+
+/** The `n`th exchange of a recording (in the order it was recorded). */
+export function exchangeAt(file: string, n: number): RecordedExchange {
+  const exchange = recording(file)[n];
+  if (exchange === undefined) throw new Error(`${file} has no exchange ${n}`);
+  return exchange;
+}
+
+/** The page's next `method` request to the exchange's path is answered with the recorded answer. */
+export async function answerWith(page: Page, exchange: RecordedExchange): Promise<void> {
+  const path = `/api${exchange.path}`;
+  await page.route(
+    (url) => url.pathname === path,
+    (handled: Route) =>
+      handled.request().method() === exchange.method
+        ? handled.fulfill({
+            status: exchange.status,
+            contentType: exchange.responseHeaders['content-type'] ?? 'application/json',
+            body: JSON.stringify(exchange.responseBody),
+          })
+        : handled.fallback(),
+  );
+}
+
+/** The recordings the W1 screens' states name (docs/ui/screens/wb-*\/screen.json). */
+export const REC = {
+  /** SELL-1, a new reference, 201: F1-MVFJOFJ8IS, then read back. */
+  sold: '003-sell-1-new-reference-201.json',
+  /** SELL-2, start today + 61, 4 policyholders, one under 16, amount 0: 422 with 4 violations. */
+  refused: '021-sell-2-start-today-61-4-policyholders-one-under-16-amount-0-422.json',
+  /** GET-1, a sold policy read back in full: F2-MVFJQA9DQG, sold then read. */
+  readBack: '045-get-1-sold-policy-reads-back-in-full-200.json',
+  /** GET-1, an unknown reference: 404. */
+  unknown: '053-get-1-unknown-reference-404.json',
+} as const;
diff --git a/tests/web/e2e/W1/support/reference.ts b/tests/web/e2e/W1/support/reference.ts
new file mode 100644
index 00000000..ca935e4e
--- /dev/null
+++ b/tests/web/e2e/W1/support/reference.ts
@@ -0,0 +1,105 @@
+// Parity with W1's derived reference (docs/ui/derived/W1/<screen>/<state>.html), structure first: the tagged
+// regions in order, the catalogued components inside each, the shell's own components, the title and the
+// navigation. The reference names a component by its data-comp root ("<id> · <tier> · <state>"); the built page
+// may carry the same data-comp root, or the kit's own class for it (kit-<id>__<part>, the stylekit's CSS-module
+// name), and either counts. The same reading as U0b's (tests/web/e2e/U0b/support/reference.ts), on W1's pages.
+import { join } from 'node:path';
+import { pathToFileURL } from 'node:url';
+import type { BrowserContext, Page } from '@playwright/test';
+import { repoRoot } from './api';
+
+export const derivedDir = join(repoRoot, 'docs', 'ui', 'derived', 'W1');
+/** The design fixture's trace.json, so the shell shows the snapshot the references were derived from. */
+export const designFixtureDir = join(repoRoot, 'docs', 'ui', 'fixture');
+
+export interface Region {
+  slug: string;
+  req: string[];
+  built: boolean;
+  comps: string[];
+}
+
+export interface Structure {
+  title: string;
+  regions: Region[];
+  /** Components outside every region: the shell's. */
+  shell: string[];
+  /** Not-built nav entries in the primary nav, by label. */
+  navNotBuilt: string[];
+  /** Links in the primary nav, by label. */
+  navLinks: string[];
+  navCurrent: string[];
+}
+
+interface Wanted {
+  regions: Record<string, string[]>;
+  shell: string[];
+}
+
+/** Runs in the page. `want` null reads a reference; given the reference's components, it reads a built page. */
+function readStructure(want: Wanted | null): Structure {
+  const idOf = (el: Element): string => (el.getAttribute('data-comp') ?? '').split('·')[0]?.trim() ?? '';
+  const outside = (el: Element): boolean => el.closest('[data-region]') === null;
+  const unique = (ids: string[]): string[] => [...new Set(ids.filter((id) => id !== ''))].sort();
+  const roots = (scope: ParentNode, id: string): Element[] =>
+    Array.from(scope.querySelectorAll(`[data-comp^="${id} "], [class^="kit-${id}__"], [class*=" kit-${id}__"]`));
+  const text = (el: Element): string => (el.textContent ?? '').replace(/\s+/g, ' ').trim();
+
+  const regions = Array.from(document.querySelectorAll('[data-region]')).map((el) => {
+    const slug = el.getAttribute('data-region') ?? '';
+    const comps = want
+      ? (want.regions[slug] ?? []).filter((id) => roots(el, id).length > 0)
+      : unique(Array.from(el.querySelectorAll('[data-comp]')).map(idOf));
+    return {
+      slug,
+      req: (el.getAttribute('data-req') ?? '').split(/\s+/).filter((r) => r !== '').sort(),
+      built: el.getAttribute('data-built') !== 'false',
+      comps: unique(comps),
+    };
+  });
+  const shell = want
+    ? want.shell.filter((id) => roots(document, id).some(outside))
+    : unique(Array.from(document.querySelectorAll('[data-comp]')).filter(outside).map(idOf));
+
+  const nav = document.querySelector('nav[aria-label^="Primary"]');
+  return {
+    title: document.title,
+    regions,
+    shell: unique(shell),
+    navNotBuilt: nav ? Array.from(nav.querySelectorAll('[data-kind="nav entry"]')).map((el) => text(el).replace(/\s*not built yet\s*$/, '')) : [],
+    navLinks: nav ? Array.from(nav.querySelectorAll('a')).map(text) : [],
+    navCurrent: nav ? Array.from(nav.querySelectorAll('[aria-current="page"]')).map(text) : [],
+  };
+}
+
+/** Reads docs/ui/derived/W1/<screen>/<state>.html in a page of its own beside the test's. */
+export async function readReference(context: BrowserContext, screen: string, state: string): Promise<Structure> {
+  const page = await context.newPage();
+  try {
+    await page.goto(pathToFileURL(join(derivedDir, screen, `${state}.html`)).href);
+    return await page.evaluate(readStructure, null);
+  } finally {
+    await page.close();
+  }
+}
+
+export async function readBuilt(page: Page, reference: Structure): Promise<Structure> {
+  const want: Wanted = {
+    regions: Object.fromEntries(reference.regions.map((r) => [r.slug, r.comps])),
+    shell: reference.shell,
+  };
+  return page.evaluate(readStructure, want);
+}
+
+/** The regions as [slug, req, built] in page order. */
+export function regionOrder(s: Structure): [string, string, boolean][] {
+  return s.regions.map((r) => [r.slug, r.req.join(' '), r.built]);
+}
+
+export function regionNamed(s: Structure, slug: string): Region | undefined {
+  return s.regions.find((r) => r.slug === slug);
+}
+
+export function unbuiltComps(s: Structure): [string, string[]][] {
+  return s.regions.filter((r) => !r.built).map((r) => [r.slug, r.comps]);
+}
