+}
+
+export interface Property {
+  addressLine1: string;
+  addressLine2: string | null;
+  addressLine3: string | null;
+  postcode: string;
+}
+
+/** The body of POST /policies (the API contract). */
+export interface SellRequest {
+  reference: string;
+  type: PolicyType;
+  startDate: string;
+  amount: number;
+  autoRenew: boolean;
+  paymentMethod: PaymentMethod;
+  policyholders: Holder[];
