+                title="The API did not answer"
+                detail="No request was completed. Nothing was changed by this screen."
+                extensions={[{ name: 'error', value: answer.reason }]}
+                onRetry={() => setAttempt((n) => n + 1)}
+              />
+            ) : null
+          }
+        />
